__doc__ = """Terminal progress-bar helpers for long-running local tasks."""

from sys import stdout
from time import time


BAR_SEGMENTS = [
    " ",
    "▏",
    "▎",
    "▍",
    "▌",
    "▋",
    "▊",
    "▉",
    "█",
]


def seconds_to_timesegments(value):
    hours = int(value // 3600 + 0.1)
    value %= 3600
    minutes = int(value // 60 + 0.1)
    value %= 60
    seconds = int(value)
    millis = int((value % 1) * 1000)
    return (hours, minutes, seconds, millis)


def timesegments_to_string(hours, minutes, seconds, millis=None):
    collect = []
    if hours > 0:
        collect.append(f"{hours:d}h")
    if collect or (minutes > 0):
        collect.append(f"{minutes:02d}m")
    if (collect or (seconds > 0)) or millis is None:
        collect.append(f"{seconds:02d}s")
    if millis is not None or (not collect):
        collect.append(f"{millis:03d}ms")
    return " ".join(collect)


def format_time(value, show_millis=False):
    (hours, minutes, seconds, millis) = seconds_to_timesegments(value)
    if show_millis:
        return timesegments_to_string(hours, minutes, seconds, millis)
    return timesegments_to_string(hours, minutes, seconds, None)


class Progress:
    """simple progress base class"""

    def __init__(
        self, name, max_value, callback_done=None, callback_prog=None
    ):
        self._start_time = None
        self._finish_time = None
        self._name = name
        self._current_value = None
        self._max_value = max_value
        self._callback_done = callback_done
        self._callback_prog = callback_prog
        self.start(0)

    def _autostart(self):
        if self._start_time is None:
            self.start()

    def _check_progress(self):
        if self._callback_prog is not None:
            self._callback_prog(self)
        return self._check_finished()

    def _check_finished(self):
        if self._current_value >= self._max_value:
            self._finish_time = self.now()
            if self._callback_done is not None:
                self._callback_done(self)

    @property
    def name(self):
        """read-only access to name"""
        return self._name

    # @property
    # def eta(self):
    #     """quick access to ETA"""
    #     return self.estimate_time_arrival()

    @property
    def etr(self):
        """quick access to ETA"""
        return self.estimate_time_remaining()

    def set(self, value):
        """set the current value"""
        self._autostart()
        self._current_value = value
        self._check_progress()

    def add(self, value):
        """add to the stored value"""
        self._autostart()
        self._current_value += value
        self._check_progress()

    def start(self, value=0):
        """reset the start time, in case the process has not started yet"""
        self._start_time = self.now()
        self._current_value = value

    def now(self):
        """a wrapper for time access"""
        return time()

    @property
    def max_value(self):
        """read-only access to max value"""
        return self._max_value

    @property
    def value(self):
        """read-only access to value"""
        return min(self._current_value, self._max_value)

    @property
    def percent(self):
        """read-only access to rounded percent with 1 digit"""
        return f"{self.get_percent(1)} %"

    @property
    def start_time(self):
        """read-only access to start time"""
        return self._start_time

    @property
    def finished(self):
        """check if has finished"""
        return self.finish_time is not None

    @property
    def elapsed(self):
        """get the elapsed time"""
        if self.finished:
            return self.finish_time - self.start_time
        return self.now() - self.start_time

    def estimate_time_remaining(self):
        """estimate the remaining time"""
        if self.finished:
            return 0
        if self.value > 0:
            remaining_time = (
                self.elapsed / self.value * (self.max_value - self.value)
            )
            return remaining_time
        return None

    # def estimate_time_arrival(self):
    #     """estimate the remaining time"""
    #     if self.finished:
    #         return self.finish_time
    #    if self.value > 0:
    #         return self.start_time + self.etr
    #     return None

    @property
    def finish_time(self):
        """read-only access to finish time"""
        return self._finish_time

    def get_bar(self, width=10):
        """create a fillable bar from ascii characters"""
        if self.finished:
            return BAR_SEGMENTS[-1] * width
        relative = self.value / self.max_value
        theoretical_width = width * relative
        full = int(theoretical_width)
        remainder_index = int(
            (theoretical_width - full) * (len(BAR_SEGMENTS) - 1)
        )
        return (
            full * BAR_SEGMENTS[-1]
            + BAR_SEGMENTS[remainder_index]
            + BAR_SEGMENTS[0] * (width - full - 1)
        )

    def get_percent(self, format_spec=""):
        """get the percentage value"""
        perc_value = (self.value / self.max_value) * 100
        return f"{perc_value:{format_spec}} %"

    def get_ratio(self, format_spec):
        """get the process ratio"""
        smax_value = f"{self.max_value:{format_spec}}"
        svalue = f"{self.value:{format_spec}}"
        return f"{svalue}/{smax_value}"

    def get_elapsed(self, show_millis=True):
        """get the elapsed time"""
        return format_time(self.elapsed, show_millis=show_millis)

    def get_remaining(self, show_millis=False):
        """get the elapsed time"""
        etr = self.estimate_time_remaining()
        if etr:
            return format_time(etr, show_millis=show_millis)
        return "[??]"

    def __format__(self, format_spec=None):
        format_spec = format_spec.strip()
        alignment = ""
        if not format_spec:
            return str(self)
        if format_spec[0] in ["<", ">", "^"]:
            alignment = format_spec[0]
            format_spec = format_spec[1:]

        if format_spec[:4] == "name":
            width = format_spec[4:]
            return f"{self.name:{alignment}{width}}"

        if format_spec[:3] == "bar":
            width = format_spec[3:]
            if width == "":
                width = 10
            else:
                width = int(width)
            return f"{self.get_bar(width)}"

        if format_spec[:7] == "percent":
            fs = format_spec[7:]
            return f"{self.get_percent(fs)}"

        if format_spec[:5] == "ratio":
            fs = format_spec[5:]
            return f"{self.get_ratio(fs):{alignment}}"

        if format_spec[:3] == "etr":
            _ = format_spec[4:]
            return f"{self.get_remaining():{alignment}}"

        if format_spec[:7] == "elapsed":
            _ = format_spec[3:]
            return f"{self.get_elapsed():{alignment}}"

        raise ValueError(f"Unknown format specifier: {format_spec}")

    def __str__(self):
        if self.finished:
            return f"{self:name}: {self:bar10} {self:percent5.1f} (after {self:elapsed})"
        return f"{self:name}: {self:bar10} {self:percent5.1f} ({self:etr} remaining)"


class CountProgress(Progress):
    """Special implementation for integer values"""

    def __init__(self, name, max_value, description=None):
        if not isinstance(max_value, int):
            raise ValueError("max_value must be an integer")
        super().__init__(name, max_value, description)

    def set(self, value):
        if not isinstance(value, int):
            raise ValueError("value must be an integer")
        return super().set(value)

    def inc(self):
        """increment"""
        return self.add(1)


from time import sleep

nval = 120

pn = Progress("test normal", 1.0)
pc = CountProgress("test count", nval)
pn.start()
pc.start()

selected = pn

# print(pn, pc)
# sleep(0.1)
# pn.set(0.0001)
# pc.set(0)

stdout.write(str(selected))
stdout.flush()
sleep(0.01)

for val in range(nval):
    pn.set((1 + val) / nval)
    pc.inc()
    stdout.write("\r" + f"{str(pn): <50} | {str(pc): <50}")
    stdout.flush()
    sleep(0.01)

print()
